css:
.fx-art{position:relative;overflow:hidden;background:linear-gradient(135deg,var(--primary),color-mix(in srgb,var(--primary) 45%,var(--accent)))}
.fx-art::before,.fx-art::after{content:"";position:absolute;border-radius:50%;background:color-mix(in srgb,var(--accent) 60%,#fff);opacity:.35}
.fx-art::before{width:60%;aspect-ratio:1;right:-12%;top:-20%}.fx-art::after{width:38%;aspect-ratio:1;left:8%;bottom:-18%;opacity:.25;background:#fff}
.fx-art.a2{background:linear-gradient(160deg,var(--accent),color-mix(in srgb,var(--accent) 40%,var(--primary)))}
.fx-art.a3{background:linear-gradient(200deg,color-mix(in srgb,var(--primary) 70%,#000),var(--accent))}
.fx-lift .grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1.6em;width:min(1060px,100%)}
.fx-lift .card{background:color-mix(in srgb,var(--surface) 94%,var(--text));border:1px solid var(--border);border-radius:var(--radius);overflow:hidden;display:flex;flex-direction:column}
.fx-lift .card .fx-art{aspect-ratio:16/10}
.fx-lift .card .body{padding:1.2em 1.3em 1.4em;display:grid;gap:.55em}
.fx-lift .card .tag{justify-self:start;font-size:.72em;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--accent)}
.fx-lift .card h3{font-size:1.35em}.fx-lift .card p{opacity:.7;font-size:.95em}
.fx-lift .card a{color:var(--primary);font-weight:700;text-decoration:none;font-size:.92em;margin-top:.3em}
@media(max-width:820px){.fx-lift .grid{grid-template-columns:1fr}}
.fx-lift .card{transition:transform calc(.35s/var(--speed)) ease,box-shadow calc(.35s/var(--speed)) ease}
.fx-lift .fx-art{transition:transform calc(.6s/var(--speed)) cubic-bezier(.2,.8,.2,1)}.fx-lift .card .fx-art{transform-origin:center}
.fx-lift .media{overflow:hidden}
.fx-lift .card:hover{transform:translateY(-8px);box-shadow:0 26px 40px -24px color-mix(in srgb,var(--text) 55%,transparent)}
.fx-lift .card:hover .fx-art{transform:scale(1.08)}
@media(prefers-reduced-motion:reduce){.fx-lift .card,.fx-lift .fx-art{transition:none}}
/* touch: :hover mirrored as .is-tap */
.fx-lift .card.is-tap{transform:translateY(-8px);box-shadow:0 26px 40px -24px color-mix(in srgb,var(--text) 55%,transparent)}
.fx-lift .card.is-tap .fx-art{transform:scale(1.08)}
